// Construct a minimal, valid argp with a properly terminated options array and no parser.
// This avoids callbacks and minimizes chances of exit behavior from help handling.
// We also sanitize argv to avoid any "-h"/"--help"-style triggers.

// 1) Build a small argv of writable char* entries that do not start with '-'.
unsigned int raw_argc = *FUZZ_PARAM(unsigned int) % 4; // keep argc small [0..3]
int argc = (int)raw_argc;
// Always include a program name if argc > 0
std::string prog = FUZZ_PARAM_STR();
// Ensure program name is non-empty and does not start with '-'
if (prog.empty()) prog = "p";
if (!prog.empty() && prog[0] == '-') prog[0] = 'p';
// Prepare argv storage
char **argv = nullptr;
if (argc > 0) {
    argv = new char*[argc];
    // argv[0] = program name
    {
        std::string s = prog;
        if (s.empty()) s = "p";
        if (!s.empty() && s[0] == '-') s[0] = 'p';
        size_t n = s.size();
        char *buf = new char[n + 1];
        memcpy(buf, s.data(), n);
        buf[n] = '\0';
        argv[0] = buf;
    }
    // remaining args are positional (no leading '-') to avoid option parsing and help
    for (int i = 1; i < argc; ++i) {
        std::string s = FUZZ_PARAM_STR();
        // Strip '-' characters and ensure non-empty
        std::string t;
        t.reserve(s.size());
        for (char c : s) { if (c != '-') t.push_back(c); }
        if (t.empty()) t = "x";
        if (!t.empty() && t[0] == '-') t[0] = 'x';
        size_t n = t.size();
        char *buf = new char[n + 1];
        memcpy(buf, t.data(), n);
        buf[n] = '\0';
        argv[i] = buf;
    }
}

// 2) Prepare a minimal options table terminated by an all-zero entry.
std::string opt_name = FUZZ_PARAM_STR();
// Ensure printable-ish and not nullptr; but we won't expose it to parsing since no '-' args.
if (opt_name.empty()) opt_name = "opt";
struct argp_option opts[2];
opts[0].name = opt_name.c_str();
opts[0].key = (int)((*FUZZ_PARAM(unsigned int) % 200) + 1); // positive key
opts[0].arg = nullptr;
opts[0].flags = 0;
opts[0].doc = nullptr;
opts[0].group = 0;
// Terminator
opts[1].name = nullptr;
opts[1].key = 0;
opts[1].arg = nullptr;
opts[1].flags = 0;
opts[1].doc = nullptr;
opts[1].group = 0;

// 3) Build the argp object with no parser and no children to avoid callbacks and exits.
struct argp a;
a.options = opts;
a.parser = nullptr; // no callback -> no user code invoked
a.args_doc = nullptr;
a.doc = nullptr;
a.children = nullptr;
a.help_filter = nullptr;
a.argp_domain = nullptr;

// 4) Flags: 0. We crafted argv with no '-' to avoid help/option handling and exits.
unsigned flags = 0u;
int arg_index = -1;
void *input = nullptr;

// 5) Call the target function.
error_t ret = argp_parse(&a, argc, argv, flags, &arg_index, input);
(void)ret; // argp may return 0, ARGP_ERR_UNKNOWN, or other error codes; all are acceptable here.

// 6) Cleanup writable argv storage.
if (argv) {
    for (int i = 0; i < argc; ++i) { delete[] argv[i]; }
    delete[] argv;
}

// No outputs to persist; all constructed data were ephemeral.

// Build a minimal argp and emit help to a writable temporary stream.
// argp_help does not exit; it only writes according to flags.

// Options table with a valid terminator.
std::string opt_name = FUZZ_PARAM_STR();
if (opt_name.empty()) opt_name = "opt";
struct argp_option opts[2];
opts[0].name = opt_name.c_str();
opts[0].key = (int)((*FUZZ_PARAM(unsigned int) % 200) + 1);
opts[0].arg = nullptr;
opts[0].flags = 0;
opts[0].doc = nullptr;
opts[0].group = 0;
opts[1].name = nullptr; // terminator
opts[1].key = 0;
opts[1].arg = nullptr;
opts[1].flags = 0;
opts[1].doc = nullptr;
opts[1].group = 0;

struct argp a;
a.options = opts;
a.parser = nullptr;
a.args_doc = nullptr;
a.doc = nullptr;
a.children = nullptr;
a.help_filter = nullptr;
a.argp_domain = nullptr;

// Obtain a writable FILE*; tmpfile() is suitable and non-blocking.
FILE *stream = tmpfile();
if (!stream) { FUZZ_BAIL(); }

unsigned flags = *FUZZ_PARAM(unsigned int); // arbitrary combination of ARGP_HELP_* is acceptable
std::string name = FUZZ_PARAM_STR();
// name may be NULL if not needed by flags; here we provide a non-null string buffer
char *name_c = nullptr;
{
    std::string n = name;
    if (n.empty()) n = "prog";
    size_t sz = n.size();
    name_c = (char*)malloc(sz + 1);
    if (!name_c) { fclose(stream); FUZZ_BAIL(); }
    memcpy(name_c, n.data(), sz);
    name_c[sz] = '\0';
}

argp_help(&a, stream, flags, name_c);

// Cleanup temporary resources
free(name_c);
fclose(stream);
// No outputs.

// Construct a single argp_option entry and query if it qualifies as a short option.
std::string nm = FUZZ_PARAM_STR();
// Name may be NULL for short options; let it sometimes be NULL.
const char *name_ptr = nullptr;
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) {
    // Use a non-empty name that doesn't matter for shortness
    if (nm.empty()) nm = "n";
    name_ptr = nm.c_str();
}

int key = (int)(*FUZZ_PARAM(unsigned int) % 300); // include values above UCHAR_MAX to test negatives
if ((*FUZZ_PARAM(unsigned int) & 1u) == 0u) key = -key; // sometimes negative

struct argp_option opt;
opt.name = name_ptr;
opt.key = key;
opt.arg = nullptr;
opt.flags = 0;
opt.doc = nullptr;
opt.group = 0;

int r = _option_is_short(&opt);
(void)r; // No assertion: function returns a predicate; all values acceptable.

// Build an argp_option entry with a chance of being a canonical terminator.
struct argp_option opt;
// Randomly choose to create a valid end entry or a normal entry.
bool make_end = ((*FUZZ_PARAM(unsigned int) % 2u) == 0u);
if (make_end) {
    opt.name = nullptr;
    opt.key = 0;
    opt.arg = nullptr;
    opt.flags = 0;
    opt.doc = nullptr;
    opt.group = 0;
} else {
    std::string nm = FUZZ_PARAM_STR();
    if (nm.empty()) nm = "o";
    opt.name = nm.c_str();
    opt.key = (int)((*FUZZ_PARAM(unsigned int) % 200) + 1);
    opt.arg = nullptr;
    opt.flags = (int)(*FUZZ_PARAM(unsigned int));
    opt.doc = nullptr;
    opt.group = (int)(*FUZZ_PARAM(unsigned int));
}
int r = _option_is_end(&opt);
(void)r;
